insert into public.examen_preguntas (nivel,tema,pregunta,opciones,correcta,explicacion) values
('principiante','Qué es IA','¿Cuál describe mejor la relación entre IA, Machine Learning e IA Generativa?','["Son tres tecnologías distintas y sin relación entre sí", "La IA generativa es parte del Machine Learning, que a su vez es parte de la IA", "El Machine Learning es más amplio que la Inteligencia Artificial", "La IA generativa es lo mismo que la Inteligencia Artificial"]'::jsonb,1,'Son círculos concéntricos: la IA es el campo más amplio, el ML es un subconjunto, y la IA generativa es un tipo de ML.'),
('principiante','Alucinaciones','¿Por qué un modelo de lenguaje a veces afirma datos falsos con total seguridad?','["Porque tiene errores de conexión a internet", "Porque copia mal de una base de datos", "Porque predice la palabra más probable, y lo probable no siempre es lo verdadero", "Porque siempre miente a propósito"]'::jsonb,2,'Un LLM genera la continuación estadísticamente más probable; cuando no ''sabe'', igual produce algo plausible pero falso: eso es una alucinación.'),
('principiante','Prompts','¿Cuáles son las 4 piezas de un buen prompt?','["Rol, tarea, contexto y formato", "Nombre, fecha, lugar y hora", "Introducción, desarrollo, conclusión y despedida", "Pregunta, respuesta, ejemplo y resumen"]'::jsonb,0,'Un prompt efectivo define quién es la IA (rol), qué hacer (tarea), lo que solo tú sabes (contexto) y cómo entregarlo (formato).'),
('principiante','Verificar','¿Cuál de estas respuestas de IA es la que MÁS conviene verificar antes de usar?','["''Para un correo claro, ve al grano en la primera frase''", "''Un buen resumen captura las ideas principales''", "''Según el estudio de Martínez (2021), el 87% prefiere la opción B''", "''2 + 2 = 4''"]'::jsonb,2,'Citas, estudios y porcentajes exactos son donde más alucina la IA; conviene pedir la fuente y comprobarla.'),
('principiante','Seguridad','Estás usando ChatGPT en el trabajo. ¿Qué NO deberías pegar nunca?','["Un borrador de correo", "Contraseñas o datos de tarjetas de clientes", "Una pregunta general sobre Excel", "Un texto para que lo resuma"]'::jsonb,1,'Nunca metas credenciales ni datos sensibles en herramientas externas: podrían quedar registrados fuera de tu control.'),
('principiante','Chatbots','¿Qué son ChatGPT, Claude y Gemini?','["Bases de datos", "Asistentes basados en grandes modelos de lenguaje", "Hojas de cálculo", "Navegadores web"]'::jsonb,1,'Son interfaces sobre LLMs; se les habla con prompts y responden en lenguaje natural.'),
('principiante','Tokens','En términos simples, ¿qué es un ''token'' para un modelo de IA?','["Una contraseña de acceso", "Un trocito de texto (aprox. 4 caracteres) que el modelo procesa", "Una moneda para pagar", "Un tipo de archivo"]'::jsonb,1,'Los modelos no leen palabras sino tokens (~4 caracteres); se cobra y se mide por tokens de entrada y de salida.'),
('principiante','IA Generativa','¿Cuál es un ejemplo de IA generativa?','["Un buscador que ordena resultados", "Un modelo que crea una imagen a partir de una descripción", "Un antivirus", "Una calculadora"]'::jsonb,1,'La IA generativa crea contenido nuevo (texto, imagen, audio, video); no solo clasifica u ordena.'),
('principiante','Contexto','¿Por qué darle contexto a la IA mejora la respuesta?','["Porque hace la respuesta más larga", "Porque la IA no conoce tu situación concreta y el contexto la orienta", "Porque reduce el costo", "Porque evita que se conecte a internet"]'::jsonb,1,'El modelo no sabe nada de tu caso salvo lo que le digas; el contexto (lo que solo tú conoces) es lo que personaliza la respuesta.'),
('principiante','Límites','¿Cuál es una limitación real de los chatbots de IA?','["No pueden escribir en español", "Pueden inventar datos y no siempre tienen información actualizada", "Solo funcionan de noche", "Nunca se equivocan"]'::jsonb,1,'Además de alucinar, muchos modelos tienen una fecha de corte de conocimiento y no conocen hechos recientes.'),
('principiante','Prompts','¿Qué falta en este prompt para mejorarlo? ''Escríbeme algo sobre ventas.''','["Nada, está perfecto", "Rol, tarea concreta, contexto y formato", "Solo el idioma", "Una firma"]'::jsonb,1,'Es vago: no define rol, la tarea es difusa (''algo''), no hay contexto ni formato. Un buen prompt concreta las 4 piezas.'),
('principiante','NotebookLM','¿Para qué sirve una herramienta como NotebookLM?','["Para jugar videojuegos", "Para responder con base en TUS documentos, con citas", "Para editar fotos", "Para enviar correos masivos"]'::jsonb,1,'NotebookLM te ayuda a estudiar/consultar tus propias fuentes y cita de dónde saca cada respuesta, reduciendo alucinaciones.'),
('principiante','Uso responsable','Un compañero dice ''la IA nunca se equivoca''. ¿Qué respondes?','["Tiene razón, es infalible", "Conviene verificar datos concretos porque puede alucinar", "La IA solo se equivoca en matemáticas", "Depende del color de la interfaz"]'::jsonb,1,'El criterio es el riesgo y la especificidad: hechos, cifras y citas se verifican; la orientación general suele ser confiable.'),
('principiante','Modelos','¿Qué significa que un modelo tenga una ''fecha de corte'' de conocimiento?','["Que caduca y deja de funcionar", "Que no conoce hechos ocurridos después de esa fecha", "Que solo trabaja hasta cierta hora", "Que borra tus datos en esa fecha"]'::jsonb,1,'El modelo se entrenó con datos hasta cierto momento; sin herramientas de búsqueda, no conoce lo posterior.'),
('principiante','Prompts','Si quieres una respuesta de máximo 100 palabras y en tono formal, ¿qué pieza del prompt estás usando?','["Rol", "Contexto", "Formato", "Tarea"]'::jsonb,2,'La longitud, el tono y la estructura son parte del ''formato'': cómo quieres que se entregue la respuesta.'),
('intermedio','APIs','¿Qué es una API en pocas palabras?','["Un lenguaje de programación", "Un contrato para que dos programas se pidan datos y funciones entre sí", "Un tipo de base de datos", "Una hoja de cálculo en la nube"]'::jsonb,1,'Una API expone operaciones (endpoints) que otros programas consumen; es cómo se comunican los sistemas.'),
('intermedio','JSON','¿De qué tipo es el valor en "activo": true dentro de un JSON?','["Texto (string)", "Número", "Booleano", "Nulo"]'::jsonb,2,'true/false son booleanos; el texto va entre comillas, los números sin comillas y null representa ausencia de valor.'),
('intermedio','HTTP','En una API, ¿qué suele indicar un código de estado 404?','["Todo salió bien", "El recurso no existe", "No tienes permiso", "Error del servidor"]'::jsonb,1,'200 = OK, 404 = no encontrado, 401/403 = autenticación/permiso, 500 = error del servidor.'),
('intermedio','Automatización','En n8n, Make, Zapier o Workfront Fusion, ¿qué es un ''trigger'' (disparador)?','["El paso final que envía un correo", "El evento que INICIA el flujo (algo pasa y arranca)", "Una condición if/else", "Una base de datos"]'::jsonb,1,'Todo flujo empieza por un disparador (un correo llega, una hora, un formulario); luego vienen los pasos/acciones.'),
('intermedio','RAG','¿Qué resuelve la técnica RAG (Retrieval-Augmented Generation)?','["Hace el modelo más rápido", "Le da al modelo información externa/actual relevante antes de responder", "Reduce el tamaño del modelo", "Traduce entre idiomas"]'::jsonb,1,'RAG recupera fragmentos relevantes de tus datos y se los pasa al modelo como contexto, reduciendo alucinaciones y usando info actual.'),
('intermedio','Costo','Al usar la API de un modelo, ¿qué suele costar MÁS?','["Los tokens de entrada", "Los tokens de salida (la respuesta generada)", "Ambos cuestan exactamente igual", "Solo se cobra por petición, no por tokens"]'::jsonb,1,'En la mayoría de modelos la salida se cobra bastante más que la entrada; por eso pedir respuestas concisas ahorra.'),
('intermedio','System prompt','¿Qué es un ''system prompt'' (prompt de sistema)?','["El primer mensaje del usuario", "Instrucciones base que definen el comportamiento del asistente en toda la conversación", "Un mensaje de error", "La respuesta del modelo"]'::jsonb,1,'El system prompt fija rol, tono y reglas globales; se aplica a toda la sesión, por encima de los mensajes del usuario.'),
('intermedio','Elegir modelo','Tu tarea es simple, se repite miles de veces y el costo importa. ¿Qué conviene?','["Siempre el modelo más caro/premium", "El modelo más barato que resuelva bien la tarea", "No usar IA", "Elegir al azar"]'::jsonb,1,'Reserva el premium para lo que de verdad lo necesita; en tareas simples a gran escala, el modelo económico decide la rentabilidad.'),
('intermedio','Bases de datos','¿Para qué sirve una base de datos en una app con IA?','["Para darle estilo visual", "Para guardar y consultar datos de forma estructurada y persistente", "Para entrenar el modelo en el navegador", "Para reemplazar al servidor"]'::jsonb,1,'La base de datos almacena usuarios, registros, progreso, etc., y permite consultarlos de forma fiable.'),
('intermedio','Webhooks','¿Qué es un webhook?','["Un gancho para colgar archivos", "Una URL a la que un sistema envía datos automáticamente cuando ocurre un evento", "Un tipo de contraseña", "Un modelo de IA"]'::jsonb,1,'Un webhook es una llamada HTTP que un servicio hace a tu URL cuando pasa algo; es la base de muchas automatizaciones en tiempo real.'),
('intermedio','JSON','¿Cuál es un JSON válido?','["{nombre: Ana}", "{''nombre'': ''Ana''}", "{\"nombre\": \"Ana\"}", "(nombre = Ana)"]'::jsonb,2,'JSON exige comillas dobles en las claves y en los strings; comillas simples o claves sin comillas no son JSON válido.'),
('intermedio','Automatización','¿Qué hace un ''router'' o condición en un flujo de automatización?','["Envía siempre el mismo correo", "Bifurca el flujo según una condición (si… entonces…)", "Borra la base de datos", "Traduce el texto"]'::jsonb,1,'El router evalúa condiciones y dirige el flujo por una rama u otra, permitiendo lógica distinta según el caso.'),
('intermedio','Front/Back','¿Cuál es la diferencia entre front-end y back-end?','["El front es la base de datos y el back el diseño", "El front es lo que ve el usuario; el back es la lógica y datos en el servidor", "Son sinónimos", "El back solo existe en apps móviles"]'::jsonb,1,'Front-end = interfaz en el navegador; back-end = servidor, lógica de negocio y datos. La API los conecta.'),
('intermedio','Prompt engineering','¿Qué técnica suele mejorar el razonamiento del modelo en problemas de varios pasos?','["Pedirle que responda lo más corto posible", "Pedirle que ''piense paso a paso'' antes de dar la respuesta", "Escribir todo en mayúsculas", "Repetir la pregunta 3 veces"]'::jsonb,1,'Pedir razonamiento paso a paso (chain-of-thought) ayuda al modelo a descomponer el problema y acertar más en tareas complejas.'),
('intermedio','Embeddings','¿Qué es un ''embedding''?','["Una imagen incrustada", "Una representación numérica del significado de un texto", "Un tipo de contraseña", "Un formato de video"]'::jsonb,1,'Un embedding convierte texto en un vector de números que captura su significado; textos parecidos quedan cerca, y es la base de la búsqueda semántica y RAG.'),
('avanzado','Agentes','¿Qué distingue a un ''agente de IA'' de un chatbot normal?','["El agente responde más rápido", "El agente puede razonar, decidir y USAR herramientas para actuar en varios pasos", "El agente solo funciona en móvil", "No hay diferencia"]'::jsonb,1,'Un agente no solo conversa: planifica, llama herramientas (APIs, búsquedas, acciones) y encadena pasos hacia un objetivo.'),
('avanzado','Prompt injection','¿Qué es un ataque de ''prompt injection''?','["Inyectar SQL en una base de datos", "Texto malicioso (en una web, correo o documento) que intenta secuestrar las instrucciones del modelo", "Un error de tipografía", "Una forma de acelerar el modelo"]'::jsonb,1,'En prompt injection, contenido que el agente lee (no el usuario) trae órdenes ocultas; por eso el contenido externo es DATO, no instrucciones a obedecer.'),
('avanzado','Scraping','Al hacer web scraping de forma responsable, ¿qué debes respetar?','["Nada, todo es libre", "robots.txt, los términos del sitio, y no saturar el servidor", "Solo scrapear de noche", "Copiar datos personales sin límite"]'::jsonb,1,'Scraping responsable: revisar robots.txt y términos, poner pausas entre peticiones, evitar datos personales sin base legal y preferir la API oficial si existe.'),
('avanzado','Selectores','En scraping, para extraer todos los precios marcados con class=''precio'', ¿qué selector CSS usas?','["#precio", ".precio", "precio()", "<precio>"]'::jsonb,1,'El punto selecciona por clase (.precio); la almohadilla (#) es por id, y una etiqueta se escribe por su nombre sin símbolos.'),
('avanzado','Orquestación','En un flujo agéntico, ¿cuál es un patrón universal válido?','["Acción → Disparador → Agente", "Disparador → Agente de IA → Acción", "Solo un agente sin nada más", "Router → Router → Router"]'::jsonb,1,'El patrón se repite en Fusion/n8n/Make/Zapier: algo dispara, uno o más pasos transforman (hoy muchos con un agente de IA) y ocurre una acción.'),
('avanzado','SQL injection','¿Cómo se previene de raíz una inyección SQL?','["Ocultando el formulario", "Con consultas parametrizadas (el texto del usuario viaja como DATO, no como código)", "Poniendo contraseñas largas", "Usando HTTPS únicamente"]'::jsonb,1,'La causa es concatenar texto del usuario en la consulta; las consultas parametrizadas tratan la entrada como dato literal, no como SQL ejecutable.'),
('avanzado','MCP','¿Qué permite el Model Context Protocol (MCP)?','["Comprimir modelos", "Conectar de forma estandarizada un modelo con herramientas y fuentes de datos externas", "Traducir código", "Reducir el costo de tokens a cero"]'::jsonb,1,'MCP estandariza cómo un modelo/agente accede a herramientas, recursos y prompts externos, como un ''puerto USB'' para capacidades.'),
('avanzado','Evals','¿Para qué sirven las ''evaluaciones'' (evals) de un sistema de IA?','["Para hacerlo más bonito", "Para medir de forma sistemática si la IA responde bien y detectar regresiones", "Para entrenar al usuario", "Para reducir el tamaño de la base de datos"]'::jsonb,1,'Las evals prueban el sistema contra casos con respuesta esperada; permiten comparar prompts/modelos y saber si un cambio mejora o empeora.'),
('avanzado','Gobernanza','En una empresa, ¿qué es clave para usar IA de forma responsable?','["Prohibirla por completo", "Definir qué datos se pueden usar, con qué modelos y con qué permisos (gobernanza)", "Usar siempre el modelo más grande", "No documentar nada"]'::jsonb,1,'La gobernanza fija políticas de privacidad, elección de modelo, permisos y trazabilidad; sin ella, el uso de IA se vuelve un riesgo.'),
('avanzado','APIs ocultas','¿Qué es una ''API oculta'' en el contexto de scraping avanzado?','["Una API secreta del gobierno", "El endpoint interno (JSON) que la propia web usa y que puedes llamar directamente", "Una API que no existe", "Un tipo de captcha"]'::jsonb,1,'Muchas webs cargan datos vía peticiones JSON internas; llamarlas directamente suele ser más limpio y estable que raspar el HTML.'),
('avanzado','Agentes','¿Qué es el patrón ''humano en el bucle'' (human-in-the-loop)?','["Un agente sin supervisión", "Una persona aprueba o revisa antes de que el agente ejecute acciones sensibles", "Un bucle infinito", "Un tipo de base de datos"]'::jsonb,1,'Para acciones de riesgo (enviar dinero, publicar, borrar), se intercala una aprobación humana antes de que el agente actúe.'),
('avanzado','Costo/latencia','Un agente hace muchas llamadas al modelo por tarea. ¿Qué considerar?','["Nada, el costo es fijo", "Que el costo y la latencia se multiplican por cada paso, y hay que optimizarlos", "Que siempre es gratis", "Que la respuesta será peor"]'::jsonb,1,'Cada paso de un agente es una llamada con su costo y demora; en producción se optimizan pasos, modelo por paso y caché.'),
('avanzado','Seguridad datos','Al conectar un agente a herramientas, ¿qué principio de seguridad aplicar?','["Darle todos los permisos posibles", "Permisos mínimos: solo lo que necesita para su tarea", "No usar autenticación", "Compartir la clave secreta en el frontend"]'::jsonb,1,'El principio de mínimo privilegio limita el daño si algo falla o es atacado; nunca expongas claves secretas en el navegador.'),
('avanzado','RAG avanzado','En un sistema RAG, ¿qué problema causa recuperar fragmentos irrelevantes?','["Ninguno", "El modelo puede responder con base en contexto equivocado y ''alucinar con fuentes''", "El modelo se apaga", "Reduce el costo a cero"]'::jsonb,1,'La calidad de RAG depende de la recuperación; si trae fragmentos malos, el modelo genera respuestas confiadas pero incorrectas.'),
('avanzado','Despliegue','¿Por qué validar la salida de un modelo antes de usarla en un sistema automático?','["Para que sea más larga", "Porque puede venir mal formada o incorrecta y romper pasos posteriores", "No hace falta nunca", "Para gastar más tokens"]'::jsonb,1,'En un flujo automático, una salida inesperada (JSON inválido, dato falso) propaga errores; validar/normalizar antes de continuar es esencial.');
